import {BatchRunner,newBatch,batchProgress} from './batch-engine.js';
import {renderBatch,renderBatchHistory} from './batch-view.js';
import {readingPDF} from './reading-pdf.js';
import {readingText} from './reading-export.js';
import {exampleRecords,exampleMetadata} from './workspace-model.js';
import {renderReadingCard,renderReadingInspector,readingTitle,readingFieldState} from './reading-view.js';
import {icon,mountIcons} from './workspace-icons.js';
import {scientificCSV,scientificXLSX,researchJSONL,scientificPackage,scientificEvidenceCSV,readingEvidenceCSV} from './research-exports.js';
import {validateResearch,effectiveFields} from './research-shared.js';
import {validateAttribution,MATERIAL_ROLE_LABELS,NUMERIC_ROLE_LABELS} from './research-attribution.js';
import {readPDF} from './pdf-reader-research.js';
import {scientificFromBlocks} from './research-core.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=v=>String(v||'').replace(/\$_?(?:\{([^}]+)\}|([^$]+))\$/g,(_,a,b)=>a||b||'').replace(/\\(?:beta|alpha)/g,m=>m==='\\beta'?'β':'α');
const authors=m=>(m.authors||[]).map(x=>typeof x==='string'?x:x.name||'').filter(Boolean).slice(0,4).join('；');
const doi=v=>String(v||'').trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'').toLowerCase();
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('paperlens:'+key))??fallback;}catch{return fallback;}};
const save=(key,value)=>{try{localStorage.setItem('paperlens:'+key,JSON.stringify(value));}catch{}};
const state={batch:load('active-batch',null),batches:[],batchLimit:Number(load('batch-limit',5)),batchAuto:load('batch-auto',true),records:[],full:new Map(),selected:new Set(load('selected',[])),results:null,resultSelection:new Set(),provider:'arxiv',query:'',filter:'all',libraryQuery:'',health:null,indexLoading:true,detailTab:'reading',evidenceId:null,exportScope:'selected',exportFormat:'xlsx',jobs:load('jobs',[]).map(j=>({...j,state:['running','queued'].includes(j.state)?'paused':j.state})),running:false,paused:false,controller:null,pdfs:new Map(),pendingFileMeta:null,pendingAttach:null};
let epoch=0,searchEpoch=0,toastTimer;
const currentRoute=()=>location.hash.slice(1)||'discovery';
const labels={discovery:'文献检索',library:'我的文献库',jobs:'批次任务',exports:'导出文件',compare:'文献比较',settings:'使用说明与设置',upload:'导入论文',paper:'文献详情'};
function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;toastTimer=setTimeout(()=>{el.hidden=true;},6500);}
function storeJobs(){save('jobs',state.jobs.map(({file,pdf,...j})=>j));$('#jobs-count').textContent=state.jobs.filter(j=>!['done'].includes(j.state)).length||'';}
function storeSelected(){save('selected',[...state.selected]);}
async function request(url,options={}){const response=await fetch(url,options);let data;try{data=await response.json();}catch{throw Error('服务器没有返回可读取的数据，请重试。');}if(!response.ok)throw Error(data.error||'请求未完成，请重试。');return data;}
async function reloadLibrary(){let cursor='',records=[];do{const data=await request('/api/research/index'+(cursor?'?cursor='+encodeURIComponent(cursor):''));records.push(...data.records);cursor=data.cursor||'';}while(cursor&&records.length<2000);state.records=[...new Map(records.map(r=>[r.id,r])).values()];state.indexLoading=false;$('#library-count').textContent=state.records.length;return state.records;}
async function getRecord(id){let record=state.full.get(id);if(!record){record=await request('/api/research/record?id='+encodeURIComponent(id));validateResearch(record);if(record.attribution)validateAttribution(record);state.full.set(id,record);}const summary=state.records.find(r=>r.id===id);return {...record,review:summary?.review||null};}
async function recordsForScope(scope=state.exportScope){const ids=scope==='all'?state.records.map(r=>r.id):state.records.filter(r=>state.selected.has(r.id)).map(r=>r.id);if(!ids.length)throw Error('请先在文献库选择论文，或明确选择“全部文献”。');return Promise.all(ids.map(getRecord));}
function status(record){if(record.reading_card)return '<span class="status warning"><span class="small-dot"></span>阅读卡片待用户复核</span>';if(record.review?.decision==='reviewed'&&!record.review.stale)return '<span class="status success"><span class="small-dot"></span>原字段已复核</span>';if(record.status==='failed')return '<span class="status error"><span class="small-dot"></span>核心字段缺失</span>';if(record.status==='partial')return '<span class="status warning"><span class="small-dot"></span>字段待补全</span>';return '<span class="status muted"><span class="small-dot"></span>待人工复核</span>';}
const missing=r=>r.reading_card?['methods','findings','conclusions'].some(k=>!readingFieldState(r,k).available):['materials','methods','findings','conclusions'].some(k=>!r[k]?.length);
function subjects(r){if(r.reading_card?.objects?.length)return r.reading_card.objects.filter(o=>['study_subject','study_subject_variant','impurity_in_host','impurity_in_host_candidate','title_study_object_candidate','research_topic_not_sample'].includes(o.role)).map(o=>o.role==='research_topic_not_sample'?o.name+'（研究主题）':o.name);return r.attribution?.materials?.filter(m=>m.role==='study_subject').map(m=>m.name)||[];}
function selectedCount(){return state.records.filter(r=>state.selected.has(r.id)).length;}
function updateSelection(){storeSelected();const count=selectedCount();for(const el of document.querySelectorAll('[data-selected-count]'))el.textContent=count;for(const el of document.querySelectorAll('[data-requires-selection]'))el.disabled=!count;const visible=[...document.querySelectorAll('input[data-select]')];const master=$('#select-visible');if(master){master.checked=visible.length>0&&visible.every(e=>e.checked);master.indeterminate=visible.some(e=>e.checked)&&!master.checked;}}
function renderSampleRow(r){const names=subjects(r),meta=exampleMetadata(r);return `<article class="paper-row"><div class="paper-glyph">${icon('file')}</div><div><h3><a class="paper-title" href="#paper/${encodeURIComponent(r.id)}">${esc(plain(r.meta.title))}</a></h3><div class="paper-meta"><span>${esc(meta.source)} · ${esc(r.id)}</span><span class="dot-separator">·</span><span>${esc(String(meta.year))}</span></div><div class="paper-tags">${names.map(n=>`<span class="tag subject">${esc(n)}</span>`).join('')}${status(r)}</div></div><div class="row-action"><a class="icon-button" href="#paper/${encodeURIComponent(r.id)}" aria-label="打开 ${esc(plain(r.meta.title))}">${icon('chevron')}</a></div></article>`;}
function discovery(){const examples=exampleRecords(state.records);const example=state.records.find(r=>r.id==='2501.00680v1');const quote=example?.source_snippets?.find(s=>s.field==='findings');return `<div class="discovery-head"><h1>检索科学文献</h1><p>找到相关论文，整理材料、方法、发现与结论，让研究回到原文。</p></div><section class="search-panel" aria-label="检索真实文献"><form id="search-form"><label class="label" for="search-query">关键词、DOI 或 arXiv ID</label><div class="search-input-row"><div class="search-input-wrap">${icon('search')}<input class="search-input" id="search-query" name="q" value="${esc(state.query)}" placeholder="例如：BiFeO3 nanoparticles 或 2501.00680" autocomplete="off" maxlength="500" required></div><button class="btn search-submit" type="submit" id="search-submit">检索文献 ${icon('arrow')}</button></div><div class="search-options"><div class="source-switch"><span>检索来源</span><button class="source-button" type="button" data-provider="arxiv" aria-pressed="${state.provider==='arxiv'}">arXiv</button><button class="source-button" type="button" data-provider="crossref" aria-pressed="${state.provider==='crossref'}">Crossref</button></div><div class="search-examples"><span>试试</span><button type="button" data-example="BiFeO3 nanoparticles">BiFeO₃ 纳米颗粒</button><button type="button" data-example="solid state electrolyte">固态电解质</button><button type="button" data-example="2501.00680">2501.00680</button></div></div><div class="batch-start-row"><div class="batch-controls"><label for="batch-limit">计划获取</label><select id="batch-limit" class="input">${[5,10,20].map(n=>`<option value="${n}" ${state.batchLimit===n?'selected':''}>${n} 篇</option>`).join('')}</select><label class="check-label"><input id="batch-auto" type="checkbox" ${state.batchAuto?'checked':''}>完成后下载结果 ZIP</label></div><button class="btn primary" type="button" data-action="start-batch" ${batchRunner.active||state.running?'disabled':''}>一键爬取并生成 PDF / Excel</button></div><p class="hint">批量全文使用 arXiv：检索 → 核对许可 → 获取原文 → 自动提取 → 生成报告。每批最多 20 篇，每篇最多 25 MiB。</p><details class="report-framework-preview"><summary>报告会包含哪些内容？</summary><p>研究问题 → 对象与材料角色 → 方法路线与操作线索 → 发现 / 论点 → 作者结论 → 数值与条件 → 局限 → 原文证据。缺失项会明确标记，不自动补写。</p></details></form></section><p class="search-note">${icon('info')}仅获取开放或授权全文。Crossref 提供真实元数据，全文可能需要自行导入。</p><div id="search-results" aria-live="polite">${state.results?resultList():`<div class="discovery-grid"><section class="sample-list"><div class="sample-header"><div><h2>从真实论文开始</h2><p>已核对来源的示例，非本次实时检索结果</p></div><a href="#library" class="text-link">全部文献 ${icon('arrow')}</a></div>${state.indexLoading?'<div class="panel"><div class="skeleton"></div><div class="skeleton short"></div><div class="skeleton block"></div></div>':examples.length?examples.map(renderSampleRow).join(''):'<div class="empty"><p>还没有示例记录。你可以检索文献或导入授权 PDF。</p></div>'}</section><aside class="evidence-preview"><div class="preview-icon">${icon('quote')}</div><h2>每条发现，都有出处</h2><p>从研究记录直接回查原文页码与段落。</p><blockquote>${esc(quote?.text||'选择论文后，在证据检查区查看实际原句。')}</blockquote><div class="quote-source">${quote?'BiFeO3 纳米颗粒 · 原论文第 '+quote.page_start+' 页':'原文、页码与文件指纹一起保留'}</div>${example?`<a class="text-link" href="#paper/${encodeURIComponent(example.id)}">查看这篇论文的证据 ${icon('arrow')}</a>`:''}</aside></div>`}</div>`;}
function resultList(){const data=state.results;if(data.error)return `<div class="error-box">${esc(data.error)}<br><button class="btn small" data-action="retry-search">${icon('refresh')}重新检索</button></div>`;if(!data.items.length)return `<div class="empty">${icon('search')}<h2>没有找到匹配文献</h2><p>试试更短的英文关键词、DOI，或切换检索来源。</p><button class="btn" data-action="focus-search">调整检索词</button></div>`;const count=data.items.filter(p=>state.resultSelection.has(p.id)).length;return `<div class="search-result-header"><div><h2>检索结果 <span class="muted small">${data.items.length} 篇</span></h2><p>${esc(data.provider==='crossref'?'Crossref 真实元数据':data.provider==='openalex'?'OpenAlex 实时元数据 · arXiv 原文位置':data.scope==='PINNED_REAL_CORPUS_ID_LOOKUP'?'已核对版本的真实 arXiv 记录':'arXiv 实时检索')} · 按当前请求展示</p></div><button class="btn small" data-action="export-metadata">导出元数据 CSV</button></div><div class="selection-bar"><label class="check-label"><input type="checkbox" id="select-search" ${count===data.items.length?'checked':''}>已选择 <span id="search-selected-count">${count}</span> 篇</label><button class="btn primary small" data-action="queue-results" ${count?'':'disabled'}>${icon('download')}获取所选开放全文</button></div>${data.items.map(p=>{const existing=state.records.find(r=>r.id===p.id||p.doi&&doi(r.meta.doi)===doi(p.doi));return `<article class="result-card"><input type="checkbox" data-result="${esc(p.id)}" aria-label="选择 ${esc(plain(p.title))}" ${state.resultSelection.has(p.id)?'checked':''}><div><h3><a class="paper-title" href="${p.url.startsWith('https://')?esc(p.url):'#'}" target="_blank" rel="noopener">${esc(plain(p.title))}</a></h3><div class="paper-meta"><span>${esc(authors(p)||'作者未返回')}</span><span class="dot-separator">·</span><span>${esc(p.year||'年份未返回')}</span><span class="dot-separator">·</span><span>${esc(p.venue||p.source)}</span></div>${p.abstract?`<p class="abstract">${esc(p.abstract)}</p>`:''}<div class="result-bottom"><span class="tag">${p.source==='arxiv'?'arXiv · 可尝试开放全文':'Crossref · 元数据'}</span><div class="inline-actions">${existing?`<a class="btn small" href="#paper/${encodeURIComponent(existing.id)}">在文献库打开 ${icon('arrow')}</a>`:p.source==='arxiv'?`<button class="btn small" data-acquire="${esc(p.id)}">${icon('download')}获取并整理</button>`:`<button class="btn small" data-upload-meta="${esc(p.id)}">${icon('upload')}导入授权 PDF</button>`}<a class="text-link" href="${esc(p.url)}" target="_blank" rel="noopener">来源 ${icon('external')}</a></div></div></div></article>`;}).join('')}`;}
function library(){let rows=state.records;const total=rows.length,reviewed=rows.filter(r=>!r.reading_card&&r.review?.decision==='reviewed'&&!r.review.stale).length,gaps=rows.filter(missing).length;if(state.filter==='unreviewed')rows=rows.filter(r=>r.reading_card||r.review?.decision!=='reviewed'||r.review.stale);if(state.filter==='missing')rows=rows.filter(missing);if(state.libraryQuery.trim()){const q=state.libraryQuery.toLowerCase();rows=rows.filter(r=>[r.meta.title,r.id,r.meta.doi,...r.materials,...(r.reading_card?.objects||[]).map(o=>o.name),r.reading_card?.source_review?.title_zh||''].join(' ').toLowerCase().includes(q));}return `<div class="page-heading"><div><h1>我的文献库</h1><p>保存研究记录，检查字段与证据。原始自动结果和人工修订分别保留。</p></div><div class="heading-actions"><a class="btn" href="#upload">${icon('upload')}导入论文</a><a class="btn primary" href="#exports">${icon('download')}导出文件</a></div></div><div class="library-toolbar"><div class="filter-tabs"><button class="filter-tab ${state.filter==='all'?'active':''}" data-filter="all">全部文献 <span>${total}</span></button><button class="filter-tab ${state.filter==='unreviewed'?'active':''}" data-filter="unreviewed">待复核 <span>${total-reviewed}</span></button><button class="filter-tab ${state.filter==='missing'?'active':''}" data-filter="missing">字段待补全 <span>${gaps}</span></button></div><form id="library-filter"><label class="sr-only" for="library-query">筛选文献库</label><input class="input filter-input" id="library-query" value="${esc(state.libraryQuery)}" placeholder="搜索标题、材料或 DOI"></form></div><div class="selection-bar"><span>已选择 <strong data-selected-count>${selectedCount()}</strong> 篇 <button class="btn small ghost" data-action="clear-selection">清空选择</button></span><div class="actions"><button class="btn small" data-action="compare-selected" data-requires-selection ${selectedCount()?'':'disabled'}>${icon('columns')}比较所选</button><button class="btn primary small" data-action="export-selected" data-requires-selection ${selectedCount()?'':'disabled'}>${icon('download')}导出所选</button></div></div>${state.indexLoading?'<div class="panel"><div class="skeleton block"></div><div class="skeleton block"></div></div>':!rows.length?`<div class="panel empty">${icon('library')}<h2>${state.records.length?'没有符合筛选条件的文献':'开始建立你的文献库'}</h2><p>${state.records.length?'试着调整筛选词，或切换“全部文献”。':'检索真实文献，或导入已有授权 PDF。处理后将在这里保留科研记录。'}</p><a class="btn primary" href="#discovery">检索文献</a></div>`:`<div class="table-wrap" tabindex="0" aria-label="文献表格，可横向滚动"><table class="library-table"><thead><tr><th><input type="checkbox" id="select-visible" aria-label="选择当前筛选中的文献"></th><th>论文</th><th>研究对象 / 主题</th><th>核心字段</th><th>复核状态</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><input type="checkbox" data-select="${esc(r.id)}" aria-label="选择 ${esc(plain(r.meta.title))}" ${state.selected.has(r.id)?'checked':''}></td><td><h3><a class="paper-title" href="#paper/${encodeURIComponent(r.id)}">${esc(plain(r.meta.title))}</a></h3><div class="paper-meta"><span>${esc(r.id)}</span><span>·</span><span>${r.source_snippets?.length||0} 条证据</span></div></td><td>${subjects(r).length?subjects(r).map(n=>`<span class="tag subject">${esc(n)}</span>`).join(' '):'<span class="muted small">尚未确认</span>'}<p class="hint">${r.materials.length} 项原始材料候选</p></td><td><div class="field-availability">${[['methods','方法'],['findings','发现'],['conclusions','结论']].map(([f,n])=>`<span class="${readingFieldState(r,f).available?'':'missing'}">${n}：${readingFieldState(r,f).label}</span>`).join('')}</div></td><td>${status(r)}</td><td><a class="text-link" href="#paper/${encodeURIComponent(r.id)}">查看 ${icon('chevron')}</a></td></tr>`).join('')}</tbody></table></div>`}<p class="scope-note">${icon('info')}研究对象是规则候选；背景提及单独列出。结构状态不代表科研结论正确。</p>`;}
function snippetChips(record,field){const target=field==='materials'?'chemicals':field;const list=record.source_snippets.filter(s=>s.field===target);return `<div class="source-chips">${list.slice(0,12).map(s=>`<button class="source-chip ${state.evidenceId===s.evidence_id?'active':''}" data-evidence="${esc(s.evidence_id)}">原文 p.${s.page_start} · ${esc(s.evidence_id)}</button>`).join('')}${list.length>12?`<button class="source-chip" data-detail-tab="evidence">全部 ${list.length} 条</button>`:''}</div>`;}
function scientificFields(r){const f=effectiveFields(r,r.review);const hasReview=!!r.review?.edits&&Object.keys(r.review.edits).length>0;return `<div class="record-section"><div class="record-section-heading"><h2>材料与研究对象</h2><span class="tag">归属待复核</span></div><div class="role-grid">${['study_subject','background','comparator','reagent_or_environment'].map(role=>`<div><span class="role-label">${esc(MATERIAL_ROLE_LABELS[role]||role)}</span><div class="role-value">${esc(r.attribution?.materials?.filter(m=>m.role===role).map(m=>m.name).join('；')||'未识别 / 待确认')}</div></div>`).join('')}</div>${r.attribution?.materials?.some(m=>m.role==='uncertain')?`<p class="hint">归属不确定：${esc(r.attribution.materials.filter(m=>m.role==='uncertain').map(m=>m.name).join('；'))}</p>`:''}<details class="candidates-details"><summary>查看原始材料候选与提取版本</summary><p>${esc(r.materials.join('；')||'没有识别到材料候选')}<br>提取器：${esc(r.extractor_version)}<br>归属：${esc(r.attribution?.version||'NOT_EXECUTED_HISTORICAL_RECORD')}</p></details>${hasReview&&r.review.edits.materials!==undefined?`<p class="hint">人工修订的材料展示值：${esc(f.materials.join('；')||'已清空')}。角色候选仍保留原始自动归属。</p>`:''}${snippetChips(r,'materials')}</div>${[['methods','研究方法'],['findings','主要发现'],['conclusions','结论']].map(([field,label])=>`<section class="record-section"><div class="record-section-heading"><h2>${label}</h2>${hasReview&&r.review.edits[field]!==undefined?'<span class="tag">显示人工修订</span>':'<span class="small muted">自动原文</span>'}</div>${f[field]?`<p class="record-copy">${esc(f[field])}</p>`:`<p class="missing-copy">未提取到${label}。这可能由规则覆盖或章节识别不足引起，不代表原文没有报告。</p>`}${snippetChips(r,field)}</section>`).join('')}<section class="record-section"><div class="record-section-heading"><h2>数值候选与归属</h2><span class="small muted">未做跨条件归一化</span></div>${r.experimental_data.length?r.experimental_data.map((item,index)=>{const decision=r.attribution?.numeric?.find(n=>n.candidate_index===index),role=decision?.role||'uncertain';return `<div class="numeric-item"><span class="numeric-label ${esc(role)}">${esc(NUMERIC_ROLE_LABELS[role]||'归属未执行')}</span><p>${esc(item.text)}</p><div class="source-chips">${item.evidence_ids.map(id=>{const s=r.source_snippets.find(s=>s.evidence_id===id);return `<button class="source-chip" data-evidence="${esc(id)}">原文 p.${s?.page_start||'—'} · ${esc(id)}</button>`;}).join('')}${(decision?.context_evidence_ids||[]).map(id=>`<button class="source-chip" data-evidence="${esc(id)}">归属上下文</button>`).join('')}</div></div>`;}).join(''):'<p class="missing-copy">未识别到数值候选。</p>'}</section>${r.algorithms.length?`<section class="record-section"><h2>计算方法提及</h2><div class="paper-tags">${r.algorithms.map(a=>`<span class="tag">${esc(a.name)}</span>`).join('')}</div><p class="hint">关键词提及不等于算法创新或深度分析。</p></section>`:''}`;}
function evidenceList(r){return `<div class="panel"><h2>原文证据 <span class="small muted">${r.source_snippets.length} 条</span></h2><p class="hint">偏移以 Unicode 字符计数，左闭右开；原句存在不证明科学解释正确。</p>${r.source_snippets.map(s=>`<article class="evidence-entry"><div class="inline-actions"><span class="tag">${esc(s.field)}</span><span class="small muted">原文 p.${s.page_start} · ${esc(s.evidence_id)}</span></div><p>${esc(s.text)}</p><div class="inline-actions"><button class="source-chip" data-evidence="${esc(s.evidence_id)}">在检查区查看 ${icon('arrow')}</button><span class="hash">${esc(s.block_id)} · ${s.start_offset}:${s.end_offset}</span></div></article>`).join('')}</div>`;}
function reviewForm(r){const rev=r.review||{},f=effectiveFields(r,rev);return `<section class="panel"><h2>人工复核</h2><p class="settings-copy">自动结果会保留。修订仅作为单独覆盖层保存，证据仍指向自动结果的原文；归属候选和助手导读不随此确认自动变为已复核。</p>${rev.stale?'<div class="notice warning">PDF 版本已变更。旧修订没有应用，请重新对照原文。</div>':''}<form id="review-form" data-record="${esc(r.id)}"><div class="review-grid"><div class="field wide"><label class="label" for="review-materials">材料（用分号分隔；清空表示移除人工展示值）</label><input class="input" id="review-materials" name="materials" value="${esc(f.materials.join('; '))}"></div>${[['methods','研究方法'],['findings','主要发现'],['conclusions','结论']].map(([field,name])=>`<div class="field wide"><label class="label" for="review-${field}">${name}</label><textarea class="textarea" id="review-${field}" name="${field}" rows="5">${esc(f[field])}</textarea></div>`).join('')}<div class="field wide"><label class="label" for="review-notes">复核备注</label><textarea class="textarea" id="review-notes" name="note" placeholder="记录已核对的内容、缺失字段或仍有疑问的归属。">${esc(rev.note||'')}</textarea></div></div><label class="check-label"><input type="checkbox" name="confirmed" ${rev.decision==='reviewed'&&!rev.stale?'checked':''}>我已对照原文核查当前四个核心字段</label><div class="actions section-heading"><button class="btn primary" type="submit">${icon('check')}保存复核意见</button><span class="small muted">${rev.updated_at?'上次保存：'+esc(new Date(rev.updated_at).toLocaleString('zh-CN')):'尚未保存人工复核意见'}</span></div><div id="review-error" aria-live="polite"></div></form></section>`;}
function inspector(r){if(state.evidenceId?.startsWith('reading:'))return renderReadingInspector(r,state.evidenceId.slice(8));if(state.detailTab==='reading'&&r.reading_card){const id=r.reading_card.source_review?.question?.[0]?.evidence_ids?.[0]||r.reading_card.fields.question?.evidence_ids?.[0];return renderReadingInspector(r,id);}const snippet=r.source_snippets.find(s=>s.evidence_id===state.evidenceId)||r.source_snippets.find(s=>s.field==='findings')||r.source_snippets[0];if(!snippet)return `<aside class="evidence-inspector"><div class="inspector-header">${icon('quote')}原文证据检查</div><div class="inspector-body"><p class="small muted">此记录尚未提取到证据。可重新获取原文或人工阅读。</p></div></aside>`;state.evidenceId=snippet.evidence_id;return `<aside class="evidence-inspector" id="evidence-inspector"><div class="inspector-header">${icon('quote')}原文证据检查</div><div class="inspector-body"><div class="inspector-meta">原论文第 <strong>${snippet.page_start}</strong> 页 · ${esc(snippet.field)}<br>${esc(snippet.block_id)} · 字符 ${snippet.start_offset}–${snippet.end_offset}</div><blockquote class="inspector-quote">${esc(snippet.text)}</blockquote><button class="btn small" data-view-pdf="${esc(r.id)}" data-page="${snippet.page_start}">${icon('file')}打开对应原文页</button><p class="inspector-footnote">原句已通过字符切片校验。它证明来源片段存在，不证明归属判断或科学主张正确。</p><details class="candidates-details"><summary>文件指纹</summary><p class="hash">${esc(r.pdf_hash)}</p></details></div><div id="pdf-container"></div></aside>`;}
function detail(r){return `<a class="text-link" href="#library">${icon('back')}返回文献库</a><div class="paper-heading"><h1>${esc(readingTitle(r))}</h1><p class="reader-original-title">${esc(plain(r.meta.title))}</p><div class="paper-meta"><span>${esc(authors(r.meta)||'作者信息未记录')}</span><span>·</span><span>${esc(r.id)}</span><span>·</span>${status(r)}</div><div class="actions"><button class="btn small" data-original="${esc(r.id)}">${icon('download')}下载原始 PDF</button><button class="btn small" data-export-one="${esc(r.id)}">${icon('download')}导出本篇 Excel</button><button class="btn small" data-report-one="${esc(r.id)}">${icon('file')}生成处理报告</button>${/^https?:\/\//.test(r.meta.url||'')?`<a class="text-link" href="${esc(r.meta.url)}" target="_blank" rel="noopener">论文来源 ${icon('external')}</a>`:''}</div></div><div class="detail-layout"><div class="detail-main"><div class="detail-tabs" role="group" aria-label="文献内容">${[['reading','阅读卡片'],['record','原自动字段'],['evidence','原始证据'],['review','人工复核']].map(([id,label])=>`<button aria-pressed="${state.detailTab===id}" class="detail-tab ${state.detailTab===id?'active':''}" data-detail-tab="${id}">${label}</button>`).join('')}</div>${state.detailTab==='reading'?renderReadingCard(r):state.detailTab==='record'?scientificFields(r):state.detailTab==='evidence'?evidenceList(r):reviewForm(r)}</div>${inspector(r)}</div>`;}
function manualJobs(){const pending=state.jobs.filter(j=>j.state==='queued'||j.state==='paused').length,failed=state.jobs.filter(j=>j.state==='failed').length;const names={queued:'等待处理',running:'正在处理',paused:'已暂停',failed:'处理失败',done:'记录已保存'};return `<div class="page-heading"><div><h1>批次任务</h1><p>逐篇获取、读取和保存。已完成记录保留，重试只处理失败项。</p></div><div class="heading-actions">${state.running?`<button class="btn" data-action="pause-jobs">${icon('pause')}暂停</button>`:`<button class="btn primary" data-action="resume-jobs" ${pending?'':'disabled'}>${icon('play')}继续待处理任务</button>`}<button class="btn" data-action="retry-failed" ${failed?'':'disabled'}>${icon('refresh')}重试失败项</button></div></div><div class="notice">${icon('info')}浏览器读取 PDF 不会调用外部模型。已保存的记录保留在你的私有工作区；本地 PDF 暂存仅在当前页面有效。</div><div class="section-heading"><h2>处理队列 <span class="small muted">${state.jobs.length} 篇</span></h2><button class="btn small ghost" data-action="clear-completed">收起已完成任务</button></div>${!state.jobs.length?`<div class="panel empty">${icon('layers')}<h2>准备开始一批文献研究</h2><p>检索并选择论文，或导入本地授权 PDF。每篇的真实处理进度都会显示在这里。</p><a href="#discovery" class="btn primary">前往检索</a></div>`:`<div class="jobs-list">${state.jobs.map((j,index)=>`<article class="job-row">${icon(j.state==='done'?'circleCheck':j.state==='failed'?'info':'file')}<div><h3>${esc(plain(j.meta.title||j.meta.id))}</h3><p>${esc(j.meta.id)} · ${names[j.state]}${j.message?' · '+esc(j.message):''}</p>${j.error?`<p class="job-error">${esc(j.error)}</p>`:''}${j.state==='running'?`<progress max="100" value="${j.progress||0}" aria-label="${esc(j.message||'处理中')}"></progress>`:''}</div><div class="actions">${j.state==='done'&&j.recordId?`<a class="btn small" href="#paper/${encodeURIComponent(j.recordId)}">查看记录</a>`:j.meta.source==='local'&&j.state!=='done'&&(!j.file||j.state==='failed')?`<button class="btn small" data-reselect-job="${index}">重新选择 PDF</button>`:''}</div></article>`).join('')}</div>`}`;}
function jobs(){return manualJobs().replace('<div class="notice">',renderBatch(state.batch,batchRunner.active)+renderBatchHistory(state.batches,state.batch?.id)+'<div class="notice">');}
function exportsPage(){const count=state.exportScope==='all'?state.records.length:selectedCount();return `<div class="page-heading"><div><h1>导出研究文件</h1><p>把文献整理成可阅读、可复核、保留来源的文件。</p></div><a href="#library" class="btn">返回文献库</a></div><div class="export-layout"><section class="panel"><h2>选择导出范围</h2><div class="scope-options"><label class="check-label"><input type="radio" name="export-scope" value="selected" ${state.exportScope==='selected'?'checked':''}>已选 ${selectedCount()} 篇</label><label class="check-label"><input type="radio" name="export-scope" value="all" ${state.exportScope==='all'?'checked':''}>全部 ${state.records.length} 篇</label></div><p class="hint">当前将导出 <strong id="export-count">${count}</strong> 篇。选择不会因切换页面而清空。</p><h2 class="section-heading">选择文件格式</h2><div class="export-options">${[['xlsx','Excel 工作簿','有阅读层时增加阅读卡片、关键数值与来源；保留六张原字段审计表'],['csv','CSV 表格','适合筛选、统计或导入其他工具'],['jsonl','JSONL 完整记录','保留原始块、字符偏移、自动结果及修订'],['zip','完整资料 ZIP','表格、JSONL、证据和当前已获取的 PDF'],['report','PDF 研究报告','直接生成规范 PDF；固定章节、来源页码，无需打印']].map(([id,name,description])=>`<label class="format-choice"><input type="radio" name="export-format" value="${id}" ${state.exportFormat===id?'checked':''}><span><strong>${name}</strong><small>${description}</small></span></label>`).join('')}</div><button class="btn primary" data-action="run-export" ${count?'':'disabled'}>${icon('download')}导出 ${count} 篇文献</button><p class="hint">没有独立科研准确率金标准；导出不会把规则候选标为人工已核查。</p></section><aside><section class="export-preview"><h3>证据也一起带走</h3><ul><li>材料角色与原始候选分列</li><li>本文、引用数值与参数分开</li><li>原论文页码、块与字符偏移</li><li>自动原文、人工修订分别保留</li></ul><a class="text-link" href="#library">去选择要导出的文献 ${icon('arrow')}</a></section><section class="panel"><h3>五篇来源复核示例文件</h3><p class="settings-copy">固定语料的来源复核示例，不随本次检索更新；本批自动生成文件请到“批次任务”下载。处理报告不是原始论文。</p><div class="sample-downloads"><a class="text-link" href="/api/research/download?name=research-cards.xlsx" download>下载中文阅读卡片 Excel</a><a class="text-link" href="/api/research/download?name=research.xlsx" download>${icon('download')}五篇示例 Excel</a><a class="text-link" href="/api/research/download?name=research.jsonl" download>${icon('download')}五篇示例 JSONL</a><a class="text-link" href="/api/research/download?name=processing-report.pdf" download>${icon('download')}阅读卡片处理报告 PDF</a><a class="text-link" href="/api/research/bundle" download>${icon('download')}五篇原始 PDF 与处理文件</a></div></section></aside></div>`;}
function settings(){return `<div class="page-heading"><div><h1>使用说明与设置</h1><p>了解当前工作区能做什么，以及每项结果的实际边界。</p></div></div><div class="settings-grid"><section class="panel"><h2>当前能力</h2><ul class="settings-list"><li><span>真实文献检索</span><strong>arXiv / Crossref</strong></li><li><span>PDF 读取与规则整理</span><strong>浏览器内执行</strong></li><li><span>研究记录与复核</span><strong>${state.health?.storage?'私有工作区已连接':'存储待连接'}</strong></li><li><span>深度模型提取</span><span class="status warning">未配置 · 未执行</span></li><li><span>扫描件 OCR</span><span class="status warning">浏览器版未提供</span></li></ul><div class="notice section-heading">${icon('lock')}工作区仅你可访问。本地 PDF 在当前浏览器读取，科研记录与摘录保存到你的私有工作区，不发送给外部模型。</div></section><section class="panel"><h2>如何判断自动结果</h2><p class="settings-copy">材料提及不等于本文研究对象，引用结果不等于本文新发现。归属不确定时需要回查全文。</p><p class="settings-copy">“结构完整”只描述字段和证据结构；原句切片存在不证明科学主张正确。方法、发现和结论不保证完整。</p><p class="settings-copy">真实示例增加了独立阅读层，原规则字段及结构状态仍保留。中文示例导读由助手对照原文整理，不是自动摘要或独立专家金标准，全部仍需用户复核。</p><button class="btn small" data-action="clear-pdfs">清除当前浏览器暂存 PDF</button><p class="hint">不删除工作区的研究记录、历史或复核意见。</p></section><section class="panel"><h2>获取、复核、导出</h2><ol class="import-help"><li>检索关键词、DOI 或 arXiv ID；Crossref 结果可能仅有元数据。</li><li>选择 arXiv 论文尝试获取开放全文，或导入你有权处理的 PDF。</li><li>打开研究记录，点击页码查看实际原句，再保存复核意见。</li><li>在文献库选择论文，明确导出范围并下载文件。</li></ol></section><section class="panel"><h2>记录与版本</h2><p class="settings-copy">托管版使用独立的 research-1 规则记录，不自动迁移 Python ScientificRecord 或旧数据库。</p><p class="settings-copy">浏览器 PDF.js 与本地 PyMuPDF 是不同解析器，结果可能不同。记录保存各自真实提取版本，不把两者当作相同模型输出。</p><p class="settings-copy">一键批次的原文、记录和生成文件可跨设备下载；处理期间保持标签页开启，中断后可继续检查点。手动导入的本地 PDF 临时文件刷新后需要重新选择。在线来源限流或不可用时会保留失败原因。</p></section></div>`;}
function uploadPage(){return `<div class="page-heading"><div><h1>导入已有论文</h1><p>使用你有权处理的 PDF，或导入已有的 research-1 JSONL 记录。</p></div></div><section class="panel"><div class="import-area">${icon('upload')}<h2>把文献放进研究工作台</h2><p>PDF 在当前浏览器读取；自动结果保存到你的私有文献库。支持单篇或小批量，最多 50 篇。</p><div class="actions"><button class="btn primary" data-action="choose-pdfs">${icon('upload')}选择 PDF 文件</button><button class="btn" data-action="choose-records">导入 JSONL 记录</button></div></div><div class="review-grid section-heading"><div><label class="label" for="upload-title">论文标题（单篇时可选）</label><input class="input" id="upload-title" placeholder="不填写时使用文件名"></div><div><label class="label" for="upload-doi">DOI（单篇时可选）</label><input class="input" id="upload-doi" placeholder="10.xxxx/…"></div></div><ul class="import-help"><li>单篇不超过 100 MiB，当前浏览器暂存 PDF 合计不超过 300 MiB。</li><li>扫描件可能没有可提取文字，浏览器版不提供 OCR。</li><li>JSONL 保留来源、偏移和版本；不是 ScientificRecord 的隐式迁移入口。</li><li>证据或格式校验失败的条目会被隔离，不覆盖已有数据。</li></ul></section>`;}
async function comparePage(){const records=await recordsForScope('selected');if(records.length<2||records.length>10)return `<div class="panel empty"><h1>选择 2–10 篇论文进行比较</h1><a class="btn primary" href="#library">前往文献库</a></div>`;return `<div class="page-heading"><div><h1>文献比较</h1><p>所选 ${records.length} 篇。不同文章类型与测试条件分开理解，不按数值直接排名。助手导读和规则候选均待复核。</p></div><a class="btn" href="#library">调整选择</a></div><div class="table-wrap"><table class="compare-table"><thead><tr><th>字段</th>${records.map(r=>`<th><a href="#paper/${encodeURIComponent(r.id)}">${esc(readingTitle(r))}</a></th>`).join('')}</tr></thead><tbody>${[['question','研究问题'],['objects','研究对象 / 主题'],['methods','研究方法'],['findings','主要发现 / 论点'],['conclusions','结论'],['limitations','作者局限'],['boundaries','阅读边界']].map(([f,n])=>`<tr><th>${n}</th>${records.map(r=>`<td>${esc(readingText(r,f==='findings'&&r.reading_card?.article_type?.label==='perspective_or_review'?'arguments':f))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
async function render(){const token=++epoch,route=currentRoute(),name=route.split('/')[0];$('#route-label').textContent=labels[name]||'文献检索';for(const link of document.querySelectorAll('[data-nav]')){if(link.dataset.nav===name||(name==='paper'&&link.dataset.nav==='library'))link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}$('#sidebar').classList.remove('open');syncNavigation();try{let html;if(name==='paper'){const id=decodeURIComponent(route.slice(6));$('#content').innerHTML='<div class="panel"><div class="skeleton"></div><div class="skeleton short"></div><div class="skeleton block"></div></div>';const record=await getRecord(id);if(token!==epoch)return;html=detail(record);}else if(name==='library')html=library();else if(name==='jobs')html=jobs();else if(name==='exports')html=exportsPage();else if(name==='settings')html=settings();else if(name==='upload')html=uploadPage();else if(name==='compare'){if(!selectedCount())html='<div class="panel empty"><h1>先选择需要比较的论文</h1><p>在文献库选择 2–10 篇后查看。</p><a class="btn primary" href="#library">前往文献库</a></div>';else html=await comparePage();}else html=discovery();if(token!==epoch)return;$('#content').innerHTML=html;mountIcons($('#content'));updateSelection();document.title='PaperLens · '+(labels[name]||labels.discovery);}catch(error){if(token!==epoch)return;$('#content').innerHTML=`<div class="panel empty">${icon('info')}<h1>这个页面暂时没有打开</h1><p>${esc(error.message)}</p><button class="btn" data-action="reload-page">重试</button><a class="btn primary" href="#discovery">回到文献检索</a></div>`;}}
async function search(){const input=$('#search-query');state.query=input?.value.trim()||state.query;if(!state.query)return;const token=++searchEpoch;const target=$('#search-results');if(target)target.innerHTML='<div class="panel section-heading" role="status"><div><p class="muted">正在查询真实来源…</p><div class="skeleton"></div><div class="skeleton short"></div></div></div>';const button=$('#search-submit');if(button){button.disabled=true;button.setAttribute('aria-busy','true');}try{const result=await request('/api/discovery?'+new URLSearchParams({q:state.query,provider:state.provider}));if(token!==searchEpoch)return;state.results=result;state.resultSelection.clear();}catch(error){if(token!==searchEpoch)return;state.results={error:error.message,items:[]};}finally{if(token===searchEpoch&&currentRoute()==='discovery'){const resultTarget=$('#search-results');if(resultTarget){resultTarget.innerHTML=resultList();mountIcons(resultTarget);}const b=$('#search-submit');if(b){b.disabled=false;b.removeAttribute('aria-busy');}}}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function hash(blob){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()))].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function fetchPDF(meta,{signal,onProgress=()=>{},maxBytes=100*1048576,forceFresh=false}={}){const response=await fetch('/api/pdf?id='+encodeURIComponent(meta.id),{signal,cache:forceFresh?'reload':'default'});if(!response.ok){let text='全文获取失败，请稍后重试。';try{text=(await response.json()).error||text;}catch{}throw Error(text);}if(!/pdf/i.test(response.headers.get('content-type')||''))throw Error('来源没有返回 PDF。');const reader=response.body.getReader(),parts=[],total=Number(response.headers.get('content-length')||meta.bytes||meta.file_size||0);let size=0;try{for(;;){const {value,done}=await reader.read();if(done)break;size+=value.byteLength;if(size>maxBytes){await reader.cancel();throw Error('PDF 超过 '+Math.round(maxBytes/1048576)+' MiB 处理上限。');}parts.push(value);onProgress(size,total);}}finally{reader.releaseLock();}const blob=new Blob(parts,{type:'application/pdf'});if(meta.sha256&&await hash(blob)!==meta.sha256)throw Error('PDF 指纹与已核对的版本不同，已停止保存。');return blob;}
function queue(metas,files=[]){if(batchRunner.active)throw Error('一键批次正在处理，请先暂停当前批次后再导入。');let added=0;for(let i=0;i<metas.length;i++){const meta=metas[i];if(state.jobs.some(j=>j.meta.id===meta.id&&['queued','running','paused'].includes(j.state)))continue;if(state.records.some(r=>r.id===meta.id)&&!files[i])continue;state.jobs.push({meta,file:files[i]||null,state:'queued',progress:0,message:'等待处理',error:null});added++;}storeJobs();if(added){toast('已加入 '+added+' 篇任务');location.hash='jobs';runJobs();}else toast('所选论文已在文献库或处理队列中。');}
async function runJobs(){if(state.running||batchRunner.active)return;state.running=true;state.paused=false;for(const job of state.jobs){if(state.paused)break;if(job.state!=='queued')continue;if(job.meta.source==='local'&&!job.file){job.state='paused';job.message='需要重新选择原 PDF';continue;}state.controller=new AbortController();job.state='running';job.error=null;const notify=(message,progress)=>{job.message=message;if(progress!==undefined)job.progress=progress;storeJobs();if(currentRoute()==='jobs')render();};try{let blob=job.file;if(!blob){notify('获取开放全文',3);blob=await fetchPDF(job.meta,{signal:state.controller.signal,onProgress:(size,total)=>notify('已读取 '+(size/1048576).toFixed(1)+' MiB'+(total?' / '+(total/1048576).toFixed(1)+' MiB':''),total?Math.min(25,size/total*25):8)});}const cached=[...state.pdfs.values()].reduce((n,b)=>n+b.size,0);if(cached+blob.size>300*1048576)throw Error('当前浏览器 PDF 暂存超过 300 MiB，请先导出或清除暂存。');const digest=await hash(blob);const existing=state.records.find(r=>r.pdf_hash===digest||(job.meta.doi&&doi(r.meta.doi)===doi(job.meta.doi)));const meta=existing?{...existing.meta,id:existing.id,paper_id:existing.paper_id}:job.meta;const policy=await request('/research-policy.json');notify('读取 PDF 原文',28);const blocks=await readPDF(blob,policy,{signal:state.controller.signal,onProgress:text=>{const match=text.match(/(\d+)\/(\d+)/);notify(text,match?28+Number(match[1])/Number(match[2])*52:35);}});notify('整理字段与来源证据',84);const record=scientificFromBlocks(blocks,meta,policy,digest);validateResearch(record);validateAttribution(record);notify('保存研究记录',93);await request('/api/research/record',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(record)});state.pdfs.set(record.id,blob);state.full.set(record.id,record);job.state='done';job.recordId=record.id;job.message=missing(record)?'已保存；存在缺失字段，需人工复核':'已保存；仍需人工复核';job.progress=100;job.file=null;await reloadLibrary();}catch(error){if(error.name==='AbortError'||state.paused){job.state='paused';job.message='已暂停，完成记录不受影响';}else{job.state='failed';job.error=/Invalid PDF|InvalidPDF|InvalidPDFException/i.test(error.message)?'PDF 结构无效或文件已损坏。请重新选择可打开的 PDF。':/PasswordException|password/i.test(error.message)?'PDF 需要密码，请先选择你有权读取的未加密版本。':error.message;job.message='可重试当前失败项，或重新选择 PDF';}}finally{storeJobs();if(currentRoute()==='jobs')render();}}state.running=false;state.controller=null;storeJobs();if(currentRoute()==='jobs')render();}
async function original(record){let blob=state.pdfs.get(record.id);if(!blob){try{const stored=await fetch('/api/batch-pdf?sha='+record.pdf_hash);if(stored.ok){blob=await stored.blob();state.pdfs.set(record.id,blob);return blob;}}catch{}if(record.meta.source==='local'){state.pendingAttach=record.id;$('#paper-upload').click();throw Error('请重新选择这篇论文的原 PDF；将核对文件指纹。');}blob=await fetchPDF({...record.meta,id:record.id,sha256:record.pdf_hash});state.pdfs.set(record.id,blob);}return blob;}
async function openPDF(id,page){const r=await getRecord(id),blob=await original(r);if(!currentRoute().startsWith('paper/'))return;const container=$('#pdf-container');if(!container)return;container.innerHTML='';const frame=document.createElement('iframe');frame.className='pdf-view';frame.title='原论文 PDF 第 '+page+' 页';const url=URL.createObjectURL(blob);frame.src=url+'#page='+page;container.append(frame);setTimeout(()=>URL.revokeObjectURL(url),300000);}
async function report(records){download(await readingPDF(records),'PaperLens-research-report.pdf');}
async function runExport(){const button=document.querySelector('[data-action=run-export]');if(button){button.disabled=true;button.setAttribute('aria-busy','true');}try{const records=await recordsForScope();if(state.exportFormat==='report')await report(records);else if(state.exportFormat==='xlsx')download(await scientificXLSX(records),'PaperLens-research.xlsx');else if(state.exportFormat==='csv')download(new Blob([scientificCSV(records)],{type:'text/csv;charset=utf-8'}),'PaperLens-research.csv');else if(state.exportFormat==='jsonl')download(new Blob([researchJSONL(records)],{type:'application/x-ndjson'}),'PaperLens-research.jsonl');else download(await scientificPackage(records,records.map(r=>({id:r.id,meta:r.meta,pdf:state.pdfs.get(r.id)||null,state:'done'}))),'PaperLens-research-package.zip');toast('已准备 '+records.length+' 篇文献的导出文件');}finally{if(button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy');}}}
async function saveReview(form){const id=form.dataset.record,r=await getRecord(id),data=new FormData(form),edits={};for(const f of ['methods','findings','conclusions']){const value=String(data.get(f)||'');if(value!==r[f])edits[f]=value;}const materials=String(data.get('materials')||'').split(/[;；]/).map(x=>x.trim()).filter(Boolean);if(JSON.stringify(materials)!==JSON.stringify(r.materials))edits.materials=materials;const payload={record_id:r.id,revision:r.review?.revision||null,decision:data.has('confirmed')?'reviewed':'needs_review',edits,note:String(data.get('note')||'')};const button=form.querySelector('button[type=submit]');button.disabled=true;try{await request('/api/research/review?id='+encodeURIComponent(r.paper_id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await reloadLibrary();toast('复核意见已保存，自动结果保持原样。');await render();}catch(error){const el=$('#review-error');if(el){el.className='error-box';el.textContent=error.message;}throw error;}finally{if(button.isConnected)button.disabled=false;}}
async function importRecords(file){const lines=(await file.text()).split(/\r?\n/).filter(x=>x.trim());if(lines.length>50)throw Error('一次最多导入 50 条记录。');let stored=0,failed=0;for(const line of lines){try{const r=JSON.parse(line);validateResearch(r);if(r.attribution)validateAttribution(r);await request('/api/research/record',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(r)});state.full.delete(r.id);stored++;}catch{failed++;}}await reloadLibrary();toast('已导入 '+stored+' 条；'+failed+' 条未通过格式或来源校验。',!!failed);location.hash='library';if(currentRoute()==='library')render();}
function directDownload(url){const a=document.createElement('a');a.href=url;a.download='';document.body.append(a);a.click();a.remove();}
const batchRunner=new BatchRunner({request,
 search:(q,limit,signal)=>request('/api/discovery?'+new URLSearchParams({q,provider:'arxiv',limit:String(limit)}),{signal}),
 license:(id,signal)=>request('/api/license?id='+encodeURIComponent(id),{signal}),
 hash,
 pdf:async(meta,sha,options)=>{if(sha){const response=await fetch('/api/batch-pdf?sha='+sha,{signal:options.signal});if(response.ok)return response.blob();}return fetchPDF(meta,{...options,maxBytes:25*1048576});},
 storePDF:(sha,blob)=>request('/api/batch-pdf?sha='+sha,{method:'PUT',body:blob}),
 extract:async(blob,meta,sha,options)=>{const policy=await request('/research-policy.json');const blocks=await readPDF(blob,policy,options);return scientificFromBlocks(blocks,meta,policy,sha);},
 saveRecord:async r=>{await request('/api/research/record',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(r)});state.full.delete(r.id);},
 record:async id=>{const r=await request('/api/research/record?id='+encodeURIComponent(id));validateResearch(r);const rev=await request('/api/research/review?id='+encodeURIComponent(r.paper_id));if(rev)r.review=rev.pdf_hash===r.pdf_hash?rev:{...rev,decision:'needs_review',edits:{},stale:true};return r;},
 exports:async(records,batch)=>{batch.export_errors={};const files={'research.xlsx':await scientificXLSX(records,{batch}),'research.jsonl':new Blob([researchJSONL(records)],{type:'application/x-ndjson'}),'reading-evidence.csv':new Blob([readingEvidenceCSV(records)],{type:'text/csv;charset=utf-8'})};try{files['report.pdf']=await readingPDF(records,{batch});}catch(error){batch.export_errors['report.pdf']=error.message;}return files;},
 onError:error=>toast(error.message,true),
 onState:batch=>{state.batch=batch;$('#jobs-count').textContent=batchRunner.active?(batchProgress(batch).total?batchProgress(batch).done+'/'+batchProgress(batch).total:'…'):'';save('active-batch',batch);state.batches=[batch,...state.batches.filter(b=>b.id!==batch.id)];if(currentRoute()==='jobs')render();},
 onComplete:batch=>{toast(Object.keys(batch.export_errors||{}).length?'可用文件已生成；部分格式失败，请查看原因。':'本批 PDF / Excel 已生成，自动结果仍需复核。');if(state.batchAuto)directDownload('/api/batches/bundle?id='+batch.id);},
 onSettled:async()=>{$('#jobs-count').textContent='';await reloadLibrary();if(currentRoute()==='jobs')render();}
});
async function startBatch(){if(batchRunner.active||state.running)throw Error('当前处理仍在进行，请先等待完成或暂停。');if(state.provider!=='arxiv')throw Error('批量全文使用 arXiv，请先切换到 arXiv；Crossref 当前提供元数据。');const q=$('#search-query')?.value.trim();if(!q){$('#search-query')?.reportValidity();return;}state.query=q;state.batchLimit=Number($('#batch-limit')?.value||5);state.batchAuto=$('#batch-auto')?.checked??true;const batch=newBatch(q,state.batchLimit);state.batch=batch;location.hash='jobs';await render();batchRunner.run(batch).catch(error=>toast(error.message,true));}
async function continueBatch(options={}){if(!state.batch||batchRunner.active||state.running)throw Error('当前没有可继续的批次，或处理仍在进行。');const batch=await request('/api/batches?id='+state.batch.id);await batchRunner.run(batch,options);}
async function reloadBatches(){const data=await request('/api/batches');state.batches=data.batches;if(state.batch?.id){const latest=data.batches.find(b=>b.id===state.batch.id);if(latest)state.batch=latest;}else state.batch=data.batches[0]||null;if(state.batch)save('active-batch',state.batch);}
document.addEventListener('click',async event=>{const target=event.target.closest('button,a');if(!target)return;try{
 if(target.dataset.provider){state.provider=target.dataset.provider;document.querySelectorAll('[data-provider]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));return;}
 if(target.dataset.example){$('#search-query').value=target.dataset.example;state.provider='arxiv';document.querySelectorAll('[data-provider]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.provider==='arxiv')));await search();return;}
 if(target.dataset.batchOpen){if(batchRunner.active)throw Error('请先暂停当前批次后再切换批次。');state.batch=await request('/api/batches?id='+target.dataset.batchOpen);save('active-batch',state.batch);location.hash='jobs';await render();return;}
 if(target.dataset.filter){state.filter=target.dataset.filter;await render();return;}
 if(target.dataset.detailTab){state.detailTab=target.dataset.detailTab;await render();document.querySelector('.detail-tabs [data-detail-tab="'+state.detailTab+'"]')?.focus();return;}
 if(target.dataset.readingJump){document.getElementById('reading-'+target.dataset.readingJump)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});return;}
 if(target.dataset.readingEvidence){state.evidenceId='reading:'+target.dataset.readingEvidence;const record=await getRecord(decodeURIComponent(currentRoute().slice(6)));$('#evidence-inspector').outerHTML=renderReadingInspector(record,target.dataset.readingEvidence);if(window.innerWidth<950)$('#evidence-inspector').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});return;}
 if(target.dataset.evidence){state.evidenceId=target.dataset.evidence;const record=await getRecord(decodeURIComponent(currentRoute().slice(6)));const area=$('#evidence-inspector');if(area){area.outerHTML=inspector(record);document.querySelectorAll('[data-evidence]').forEach(b=>b.classList.toggle('active',b.dataset.evidence===state.evidenceId));if(window.innerWidth<950)$('#evidence-inspector').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});}return;}
 if(target.dataset.acquire){const meta=state.results.items.find(p=>p.id===target.dataset.acquire);queue([meta]);return;}
 if(target.dataset.uploadMeta){state.pendingFileMeta=state.results.items.find(p=>p.id===target.dataset.uploadMeta);$('#paper-upload').click();return;}
 if(target.dataset.viewPdf){target.disabled=true;try{await openPDF(target.dataset.viewPdf,Number(target.dataset.page||1));}finally{if(target.isConnected)target.disabled=false;}return;}
 if(target.dataset.original){target.disabled=true;try{const r=await getRecord(target.dataset.original);download(await original(r),r.id.replace(/[^\w.-]/g,'_')+'.pdf');}finally{if(target.isConnected)target.disabled=false;}return;}
 if(target.dataset.exportOne){download(await scientificXLSX([await getRecord(target.dataset.exportOne)]),'PaperLens-'+target.dataset.exportOne.replace(/[^\w.-]/g,'_')+'.xlsx');return;}
 if(target.dataset.reportOne){await report([await getRecord(target.dataset.reportOne)]);return;}
 if(target.dataset.reselectJob!==undefined){state.pendingAttach='job:'+target.dataset.reselectJob;$('#paper-upload').click();return;}
 const action=target.dataset.action;
 if(action==='start-batch')await startBatch();
 else if(action==='pause-batch'){batchRunner.pause();toast('正在保存检查点并暂停本批。');}
 else if(action==='resume-batch')await continueBatch();
 else if(action==='retry-batch')await continueBatch({retry:true});
 else if(action==='generate-batch-files')await continueBatch({regenerate:true});
 else if(action==='focus-search')$('#search-query').focus();
 else if(action==='retry-search')await search();
 else if(action==='clear-selection'){state.selected.clear();document.querySelectorAll('input[data-select]').forEach(x=>x.checked=false);updateSelection();}
 else if(action==='compare-selected')location.hash='compare';
 else if(action==='export-selected'){state.exportScope='selected';location.hash='exports';}
 else if(action==='queue-results'){const metas=state.results.items.filter(p=>state.resultSelection.has(p.id)&&p.source==='arxiv');if(!metas.length)throw Error('所选结果没有可直接获取的 arXiv 全文，请为 Crossref 记录导入授权 PDF。');const other=state.resultSelection.size-metas.length;if(other)toast(other+' 条 Crossref 元数据需要另行导入授权 PDF。');queue(metas);}
 else if(action==='export-metadata'){const columns=['标题','DOI','年份','作者','来源','原文链接'],rows=state.results.items.filter(p=>!state.resultSelection.size||state.resultSelection.has(p.id));const cell=v=>{let x=String(v||'');if(/^\s*[=+@-]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"';};const csv='\ufeff'+[columns,...rows.map(p=>[p.title,p.doi,p.year,authors(p),p.source,p.url])].map(row=>row.map(cell).join(',')).join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),'PaperLens-metadata.csv');}
 else if(action==='pause-jobs'){state.paused=true;state.controller?.abort();toast('正在暂停，已完成记录保留。');}
 else if(action==='resume-jobs'){for(const j of state.jobs)if(j.state==='paused')j.state='queued';runJobs();render();}
 else if(action==='retry-failed'){for(const j of state.jobs)if(j.state==='failed')j.state='queued';runJobs();render();}
 else if(action==='clear-completed'){state.jobs=state.jobs.filter(j=>j.state!=='done');storeJobs();render();}
 else if(action==='run-export')await runExport();
 else if(action==='choose-pdfs'){state.pendingFileMeta=null;state.pendingAttach=null;$('#paper-upload').click();}
 else if(action==='choose-records')$('#record-upload').click();
 else if(action==='clear-pdfs'){state.pdfs.clear();toast('已清除当前页面暂存 PDF，已保存研究记录不受影响。');}
 else if(action==='reload-page'){await reloadLibrary();render();}
 }catch(error){toast(error.message,true);}});
document.addEventListener('submit',event=>{if(!event.target.matches('#search-form,#library-filter,#review-form'))return;event.preventDefault();if(event.target.id==='search-form')search();else if(event.target.id==='library-filter'){state.libraryQuery=$('#library-query').value;render();}else saveReview(event.target).catch(e=>toast(e.message,true));});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='batch-limit'){state.batchLimit=Number(el.value);save('batch-limit',state.batchLimit);}else if(el.id==='batch-auto'){state.batchAuto=el.checked;save('batch-auto',state.batchAuto);}else if(el.dataset.select){el.checked?state.selected.add(el.dataset.select):state.selected.delete(el.dataset.select);updateSelection();}else if(el.id==='select-visible'){for(const box of document.querySelectorAll('input[data-select]')){box.checked=el.checked;el.checked?state.selected.add(box.dataset.select):state.selected.delete(box.dataset.select);}updateSelection();}else if(el.dataset.result||el.id==='select-search'){if(el.id==='select-search'){state.resultSelection=el.checked?new Set(state.results.items.map(p=>p.id)):new Set();document.querySelectorAll('[data-result]').forEach(b=>b.checked=el.checked);}else el.checked?state.resultSelection.add(el.dataset.result):state.resultSelection.delete(el.dataset.result);const count=state.resultSelection.size;const label=$('#search-selected-count');if(label)label.textContent=count;const button=document.querySelector('[data-action=queue-results]');if(button)button.disabled=!count;}else if(el.name==='export-scope'){state.exportScope=el.value;render();}else if(el.name==='export-format')state.exportFormat=el.value;});
$('#paper-upload').addEventListener('change',async event=>{const files=[...event.target.files];event.target.value='';if(!files.length)return;try{if(state.pendingAttach){if(state.pendingAttach.startsWith('job:')){const job=state.jobs[Number(state.pendingAttach.slice(4))];job.file=files[0];job.state='queued';state.pendingAttach=null;runJobs();render();return;}const r=await getRecord(state.pendingAttach);if(await hash(files[0])!==r.pdf_hash)throw Error('所选 PDF 指纹与原记录不一致，请选择正确文件。');state.pdfs.set(r.id,files[0]);state.pendingAttach=null;toast('原 PDF 已重新连接，可打开原文页。');return;}if(files.length>50)throw Error('一批最多 50 篇 PDF。');if(files.some(f=>f.size>100*1048576))throw Error('存在超过 100 MiB 的 PDF，请分批或在本地处理。');if(files.reduce((n,f)=>n+f.size,0)>300*1048576)throw Error('本批 PDF 超过 300 MiB 浏览器暂存上限。');const title=$('#upload-title')?.value.trim(),sourceDoi=$('#upload-doi')?.value.trim();const metas=[];for(const file of files){const digest=await hash(file),preset=files.length===1?state.pendingFileMeta:null;metas.push({...preset,id:preset?.id||'local-'+digest.slice(0,20),source:'local',title:preset?.title||(files.length===1&&title)||file.name.replace(/\.pdf$/i,''),doi:preset?.doi||(files.length===1?sourceDoi:null),url:preset?.url||'',authors:preset?.authors||[],paper_id:preset?.doi?'doi:'+doi(preset.doi):'local:'+digest});}state.pendingFileMeta=null;queue(metas,files);}catch(error){toast(error.message,true);}});
$('#record-upload').addEventListener('change',event=>{const file=event.target.files[0];event.target.value='';if(file)importRecords(file).catch(e=>toast(e.message,true));});
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');syncNavigation();if(open)$('#sidebar a')?.focus();});
window.addEventListener('hashchange',()=>{state.evidenceId=null;state.detailTab='reading';render();});
const mobileNavigation=matchMedia('(max-width:720px)');
function syncNavigation(){const closed=mobileNavigation.matches&&!$('#sidebar').classList.contains('open');$('#sidebar').inert=closed;$('#sidebar').setAttribute('aria-hidden',String(closed));$('#menu-toggle').setAttribute('aria-expanded',String(!closed&&mobileNavigation.matches));}
mobileNavigation.addEventListener('change',syncNavigation);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobileNavigation.matches&&$('#sidebar').classList.contains('open')){$('#sidebar').classList.remove('open');syncNavigation();$('#menu-toggle').focus();}});
mountIcons();storeJobs();render();
Promise.all([request('/api/health').then(data=>{state.health=data;$('#connection').innerHTML='<span class="small-dot"></span>工作区已连接';}),reloadLibrary(),reloadBatches()]).then(()=>render()).catch(error=>{state.indexLoading=false;$('#connection').classList.add('error');$('#connection').textContent='连接暂不可用';toast(error.message,true);render();});
